// Aggregates emails, extracts timestamps, counts categories, and creates WhatsApp digest
const items = $input.all();

const categories = {
  'Urgent': [],
  'Admission': [],
  'Finance': [],
  'Academics': [],
  'Faculty': [],
  'Student Affairs': [],
  'General': []
};

for (let i = 0; i < items.length; i++) {
  let analysis = {};
  try {
    const geminiResp = items[i].json.candidates[0].content.parts[0].text;
    analysis = JSON.parse(geminiResp);
  } catch (e) {
    analysis = { category: 'General', is_urgent: false, summary: 'Incoming email inquiry' };
  }

  // Pull original email metadata from Gmail node
  const rawEmail = $('Fetch Unread Emails (Gmail)').all()[i].json;
  const rawDate = rawEmail.internalDate || rawEmail.Date || new Date().toISOString();

  // Format arrival time e.g. [09:15 AM]
  const dateObj = new Date(parseInt(rawDate) || rawDate);
  const hours = dateObj.getHours();
  const minutes = dateObj.getMinutes().toString().padStart(2, '0');
  const ampm = hours >= 12 ? 'PM' : 'AM';
  const timeFormatted = `[${(hours % 12 || 12).toString().padStart(2, '0')}:${minutes} ${ampm}]`;

  const sender = (rawEmail.From || 'Unknown').split('<')[0].replace(/"/g, '').trim();
  const itemRecord = {
    time: timeFormatted,
    sender: sender,
    summary: analysis.summary,
    is_urgent: analysis.is_urgent
  };

  const cat = analysis.category || 'General';
  if (categories[cat]) {
    categories[cat].push(itemRecord);
  } else {
    categories['General'].push(itemRecord);
  }
}

// Build WhatsApp markdown text
let msg = `🏛️ *DEAN'S EMAIL DIGEST*\n📅 *Date:* ${new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}\n📬 *Total Received:* ${items.length} emails\n` + '─'.repeat(22) + '\n';

msg += '*📊 Category Summary:*\n';
for (const [catName, list] of Object.entries(categories)) {
  if (list.length > 0) {
    msg += `• *${catName}:* ${list.length} email${list.length > 1 ? 's' : ''}\n`;
  }
}
msg += '─'.repeat(22) + '\n';

// Urgent section
if (categories['Urgent'].length > 0) {
  msg += '🚨 *URGENT & ACTION REQUIRED:*\n';
  for (const item of categories['Urgent']) {
    msg += `• *${item.time}* *${item.sender}*: ${item.summary}\n`;
  }
  msg += '─'.repeat(22) + '\n';
}

// Detailed breakdown with timestamp
msg += '*📋 Detailed Highlights:*\n';
for (const [catName, list] of Object.entries(categories)) {
  if (catName === 'Urgent' || list.length === 0) continue;
  msg += `\n📁 *${catName.toUpperCase()} (${list.length})*\n`;
  for (const item of list) {
    msg += `• *${item.time}* _${item.sender}_: ${item.summary}\n`;
  }
}

msg += '\n' + '─'.repeat(22) + '\n📌 _Auto-categorized & tagged in your inbox folders._';

return [{ json: { whatsapp_body: msg, total_emails: items.length } }];
